function auditProdConfig(cfg: any = {}) {
  const issues: string[] = [];
  if (cfg.https !== true) issues.push("HTTPS_REQUIRED");
  if (typeof cfg.sentryDsn !== "string" || !cfg.sentryDsn.startsWith("https://")) issues.push("MISSING_SENTRY");
  if (typeof cfg.awsRegion !== "string" || !cfg.awsRegion.trim()) issues.push("MISSING_AWS_REGION");
  if (cfg.debug === true) issues.push("DEBUG_ENABLED");
  return { ready: issues.length === 0, issues };
}
